/usr/bin/bash -lc "python3 - <<'PY'
import json,pathlib
p=json.load(open('.exp_agent/round_plan_01.json'))
for r in p['rules']:
 if r['rule']=='@security/no-commented-code':
  print('\\n',r['rule'])
  for f in r['files']:
   lines=pathlib.Path(f['relative_path']).read_text().splitlines()
   found=[]
   for loc in f['locations']:
    n=loc['line']
    if n<=len(lines) and lines[n-1].lstrip().startswith(('//','/*','*','*/')): found.append((n,lines[n-1]))
   print(f['relative_path'],found)
PY"

/usr/bin/bash -lc "jq -n --slurpfile p /workspace/.exp_agent/round_plan_01.json --slurpfile c /workspace/.exp_agent/round_completion_01.json '
  def planned:
    ["'$p[0].rules[] as $r | $r.files[] as $f | $f.locations[] |
      {rule:$r.rule, relative_path:$f.relative_path, line:.line, column:.column}];
  def reported:
    [$c[0].entity_repairs[] as $e | $e.locations[] |
      {rule:$e.rule, relative_path:$e.relative_path, line:.line, column:.column}];
  (planned) as $pall | (reported) as $call |
  ($pall | map(tojson) | unique) as $ps |
  ($call | map(tojson) | unique) as $cs |
  {
    plan_total: ($pall|length), report_total: ($call|length),
    unique_plan_total:($ps|length), unique_report_total:($cs|length),
    missing: ([$ps[] | select(. as $x | ($cs|index($x)|not))] | map(fromjson)),
    extra: ([$cs[] | select(. as $x | ($ps|index($x)|not))] | map(fromjson)),
    empty_field_repairs: [$c[0].entity_repairs[] | select((.entities|type != "array") or (.entities|length == 0) or (.invariants|type != "array") or (.invariants|length == 0) or (.evidence|type != "array") or (.evidence|length == 0) or (.transformation|type != "string") or (.transformation|length == 0) or (.status != "repaired") or (.locations|type != "array") or (.locations|length == 0)) | {rule,relative_path}],
    selected_rules_missing: ([$p[0].rules[].rule | select(. as $x | ($c[0].selected_rules|index($x)|not))]),
    selected_rules_extra: ([$c[0].selected_rules[] | select(. as $x | ([$p[0].rules[].rule]|index($x)|not))])
  }'"'"

/usr/bin/bash -lc "jq -n --slurpfile p /workspace/.exp_agent/round_plan_01.json --slurpfile c /workspace/.exp_agent/round_completion_01.json '
  def expected:
    ["'$p[0].rules[] | {rule, specs: ([.semantic_spec.core_spec_path] + [.semantic_spec.families[]?.spec_path] | unique)}] | sort_by(.rule);
  def actual:
    [$c[0].consulted_specs | to_entries[] | {rule:.key, specs:(.value|unique)}] | sort_by(.rule);
  {
    expected: expected,
    actual: actual,
    mismatch: (expected - actual) + (actual - expected),
    report_rule_file_groups: ([$c[0].entity_repairs[] | [.rule,.relative_path] | @tsv] | unique | length),
    expected_rule_file_groups: $p[0].required_rule_file_groups,
    report_schema_version: $c[0].schema_version,
    unresolved_external: $c[0].unresolved_external,
    gate_context: $c[0].gate_context
  }'"'"

