/usr/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const findings = JSON.parse(fs.readFileSync('.exp_agent/findings_round_02.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_completion_02.json', 'utf8'));
const frozen = findings.map(f => "'`${f.rule}|${f.relative_path}|${f.line}|${f.column}`).sort();
const reported = report.entity_repairs.flatMap(e => e.locations.map(l => `${e.rule}|${e.relative_path}|${l.line}|${l.column}`)).sort();
const missing = frozen.filter(x => !reported.includes(x));
const extra = reported.filter(x => !frozen.includes(x));
const malformed = report.entity_repairs.filter(e => !e.entities?.length || !e.invariants?.length || !e.evidence?.length || !e.transformation || e.status !== '"'repaired');
console.log(JSON.stringify({frozenLocations:frozen.length,reportedLocations:reported.length,missing,extra,malformed:malformed.length,ruleCount:report.selected_rules.length}, null, 2));
NODE"

/usr/bin/bash -lc "python3 - <<'PY'
import json
for name in ['round_completion_01.json','round_completion_02.json']:
 p='.exp_agent/'+name
 try:
  d=json.load(open(p))
 except Exception as e:
  print(name,e); continue
 print('\\n===',name)
 print('selected',d.get('selected_rules'))
 for e in d.get('entity_repairs',[]):
  if 'avoid-overusing' in e.get('rule','') or 'redundant' in e.get('rule','') or 'unchanged' in e.get('rule',''):
   print(json.dumps(e,ensure_ascii=False,indent=2))
PY"
